-- Nurse Love Company database update: 012_size_guides.sql
--
-- How to use: Supabase dashboard, SQL Editor, New query. Paste this whole
-- file, click Run, and wait for "Success". Run each update once, in order.
-- It stops without changing anything if it was already applied, or if the
-- previous update (011_delete_forever.sql) has not been run yet.
--
-- Generated by `npm run db:sql`. Do not edit by hand.

begin;

do $$ begin
  if exists (select 1 from schema_migrations where name = '012_size_guides.sql') then
    raise exception 'This update (012_size_guides.sql) was already applied. Nothing was changed.';
  end if;
  if not exists (select 1 from schema_migrations where name = '011_delete_forever.sql') then
    raise exception 'Run the earlier update 011_delete_forever.sql first. Nothing was changed.';
  end if;
end $$;

-- Size guides: each item that ships can have its own sizing images, shown to
-- shoppers behind a "Size guide" button on the product page. They are shown
-- as uploaded (no watermark or blur), like product photos.
alter table product_images drop constraint if exists product_images_kind_check;
alter table product_images add constraint product_images_kind_check check (kind in ('gallery','sample','detail','size_guide'));

insert into schema_migrations (name) values ('012_size_guides.sql');

-- Row level security on any new table (the store's server is unaffected).
do $$ declare t record; begin
  for t in select tablename from pg_tables where schemaname = 'public' and not rowsecurity loop
    execute format('alter table public.%I enable row level security', t.tablename);
  end loop;
end $$;

commit;
